#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef enum { TYPE_CHAR, TYPE_INT, TYPE_FLOAT, TYPE_DOUBLE } Type;

Type parse_type(const char* s) {
    if (strcmp(s, "char") == 0) return TYPE_CHAR;
    if (strcmp(s, "int") == 0) return TYPE_INT;
    if (strcmp(s, "float") == 0) return TYPE_FLOAT;
    return TYPE_DOUBLE;
}

typedef struct {
    Type type;
    union {
        signed char c;
        int i;
        float f;
        double d;
    } val;
} Value;

Value cast_val(double raw, Type target) {
    Value res;
    res.type = target;
    if (target == TYPE_CHAR) {
        int iv = (int)raw;
        res.val.c = (signed char)iv;
    } else if (target == TYPE_INT) {
        res.val.i = (int)raw;
    } else if (target == TYPE_FLOAT) {
        res.val.f = (float)raw;
    } else {
        res.val.d = (double)raw;
    }
    return res;
}

int main(void) {
    char type_str[16], val_str[64];
    if (scanf("%15s %63s", type_str, val_str) != 2) return 0;

    Type curr_type = parse_type(type_str);
    Value curr;
    curr.type = curr_type;
    if (curr_type == TYPE_CHAR) curr.val.c = (signed char)atoi(val_str);
    else if (curr_type == TYPE_INT) curr.val.i = atoi(val_str);
    else if (curr_type == TYPE_FLOAT) curr.val.f = (float)atof(val_str);
    else curr.val.d = atof(val_str);

    int n;
    if (scanf("%d", &n) != 1) return 0;

    for (int k = 0; k < n; k++) {
        char op[4], op_type_str[16], op_val_str[64], target_type_str[16];
        scanf("%3s %15s %63s %15s", op, op_type_str, op_val_str, target_type_str);
        Type op_type = parse_type(op_type_str);
        Type target_type = parse_type(target_type_str);

        Type t1 = (curr.type == TYPE_CHAR) ? TYPE_INT : curr.type;
        Type t2 = (op_type == TYPE_CHAR) ? TYPE_INT : op_type;

        Type common = TYPE_INT;
        if (t1 == TYPE_DOUBLE || t2 == TYPE_DOUBLE) common = TYPE_DOUBLE;
        else if (t1 == TYPE_FLOAT || t2 == TYPE_FLOAT) common = TYPE_FLOAT;

        double v1 = (curr.type == TYPE_CHAR) ? (double)curr.val.c :
                    (curr.type == TYPE_INT) ? (double)curr.val.i :
                    (curr.type == TYPE_FLOAT) ? (double)curr.val.f : curr.val.d;

        double v2 = (op_type == TYPE_CHAR) ? (double)(signed char)atoi(op_val_str) :
                    (op_type == TYPE_INT) ? (double)atoi(op_val_str) :
                    (op_type == TYPE_FLOAT) ? (double)(float)atof(op_val_str) : atof(op_val_str);

        double raw_res = 0;
        if (common == TYPE_DOUBLE) {
            if (op[0] == '+') raw_res = v1 + v2;
            else if (op[0] == '-') raw_res = v1 - v2;
            else if (op[0] == '*') raw_res = v1 * v2;
            else if (op[0] == '/') raw_res = v1 / v2;
        } else if (common == TYPE_FLOAT) {
            float a = (float)v1, b = (float)v2;
            float r = 0;
            if (op[0] == '+') r = a + b;
            else if (op[0] == '-') r = a - b;
            else if (op[0] == '*') r = a * b;
            else if (op[0] == '/') r = a / b;
            raw_res = (double)r;
        } else {
            int a = (int)v1, b = (int)v2;
            int r = 0;
            if (op[0] == '+') r = a + b;
            else if (op[0] == '-') r = a - b;
            else if (op[0] == '*') r = a * b;
            else if (op[0] == '/') r = a / b;
            raw_res = (double)r;
        }

        curr = cast_val(raw_res, target_type);
    }

    if (curr.type == TYPE_CHAR) printf("char %d\n", curr.val.c);
    else if (curr.type == TYPE_INT) printf("int %d\n", curr.val.i);
    else if (curr.type == TYPE_FLOAT) printf("float %.2f\n", curr.val.f);
    else printf("double %.4f\n", curr.val.d);

    return 0;
}

