#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

static const char *src;

static void skip_ws(void) {
    while (*src && isspace((unsigned char)*src)) src++;
}

static long long parse_expr(void);
static long long parse_or(void);
static long long parse_xor(void);
static long long parse_and(void);
static long long parse_shift(void);
static long long parse_add(void);
static long long parse_mul(void);
static long long parse_unary(void);
static long long parse_primary(void);

static long long parse_primary(void) {
    skip_ws();
    if (*src == '(') {
        src++; // skip '('
        long long val = parse_expr();
        skip_ws();
        if (*src == ')') src++;
        return val;
    }
    long long val = 0;
    while (*src && isdigit((unsigned char)*src)) {
        val = val * 10 + (*src - '0');
        src++;
    }
    return val;
}

static long long parse_unary(void) {
    skip_ws();
    if (*src == '~') {
        src++;
        return ~parse_unary();
    } else if (*src == '+') {
        src++;
        return parse_unary();
    } else if (*src == '-') {
        src++;
        return -parse_unary();
    }
    return parse_primary();
}

static long long parse_mul(void) {
    long long left = parse_unary();
    while (1) {
        skip_ws();
        if (*src == '*') {
            src++;
            left = left * parse_unary();
        } else if (*src == '/') {
            src++;
            long long r = parse_unary();
            left = left / r;
        } else {
            break;
        }
    }
    return left;
}

static long long parse_add(void) {
    long long left = parse_mul();
    while (1) {
        skip_ws();
        if (*src == '+') {
            src++;
            left = left + parse_mul();
        } else if (*src == '-') {
            src++;
            left = left - parse_mul();
        } else {
            break;
        }
    }
    return left;
}

static long long parse_shift(void) {
    long long left = parse_add();
    while (1) {
        skip_ws();
        if (src[0] == '<' && src[1] == '<') {
            src += 2;
            long long r = parse_add();
            left = left << r;
        } else if (src[0] == '>' && src[1] == '>') {
            src += 2;
            long long r = parse_add();
            left = left >> r;
        } else {
            break;
        }
    }
    return left;
}

static long long parse_and(void) {
    long long left = parse_shift();
    while (1) {
        skip_ws();
        if (*src == '&' && src[1] != '&') {
            src++;
            left = left & parse_shift();
        } else {
            break;
        }
    }
    return left;
}

static long long parse_xor(void) {
    long long left = parse_and();
    while (1) {
        skip_ws();
        if (*src == '^') {
            src++;
            left = left ^ parse_and();
        } else {
            break;
        }
    }
    return left;
}

static long long parse_or(void) {
    long long left = parse_xor();
    while (1) {
        skip_ws();
        if (*src == '|' && src[1] != '|') {
            src++;
            left = left | parse_xor();
        } else {
            break;
        }
    }
    return left;
}

static long long parse_expr(void) {
    return parse_or();
}

int main(void) {
    char buffer[512];
    if (!fgets(buffer, sizeof(buffer), stdin)) return 0;
    src = buffer;
    printf("%lld\n", parse_expr());
    return 0;
}

