void classify(long long n) {
    if (n <= 1) {
        printf("%lld DEFICIENT 0\n", n);
        return;
    }
    long long sum = 1;
    for (long long d = 2; d * d <= n; d++) {
        if (n % d == 0) {
            sum += d;
            if (d * d != n) {
                sum += n / d;
            }
        }
    }
    if (sum == n) {
        printf("%lld PERFECT %lld\n", n, sum);
    } else if (sum > n) {
        printf("%lld ABUNDANT %lld\n", n, sum);
    } else {
        printf("%lld DEFICIENT %lld\n", n, sum);
    }
}

int main(void) {
