#include <stdio.h>

static long long ipow(long long base, int exp) {
    long long res = 1;
    while (exp > 0) {
        if (exp & 1) res *= base;
        base *= base;
        exp >>= 1;
    }
    return res;
}

static int is_armstrong(long long n) {
    if (n < 10) return 1;
    int digits = 0;
    long long temp = n;
    while (temp > 0) {
        digits++;
        temp /= 10;
    }
    long long sum = 0;
    temp = n;
    while (temp > 0) {
        int d = temp % 10;
        sum += ipow(d, digits);
        if (sum > n) return 0;
        temp /= 10;
    }
    return sum == n;
}

int main(void) {
    long long L, R;
    if (scanf("%lld %lld", &L, &R) != 2) return 0;

    int found = 0;
    for (long long i = L; i <= R; i++) {
        if (is_armstrong(i)) {
            if (found) printf(" ");
            printf("%lld", i);
            found = 1;
        }
    }
    if (!found) {
        printf("NONE\n");
    } else {
        printf("\n");
    }
    return 0;
}

