#include <stdio.h>
#include <string.h>
#include <ctype.h>

static int char_val(char c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'z') return c - 'a' + 10;
    if (c >= 'A' && c <= 'Z') return c - 'A' + 10;
    return -1;
}

static char val_char(int v) {
    if (v < 10) return '0' + v;
    return 'A' + (v - 10);
}

static void solve_one(void) {
    int b1, b2;
    char s[128];
    if (scanf("%d %d %127s", &b1, &b2, s) != 3) return;

    int negative = 0;
    int idx = 0;
    if (s[0] == '-') {
        negative = 1;
        idx = 1;
    }
    if (s[idx] == '\0') {
        printf("INVALID\n");
        return;
    }

    unsigned long long val = 0;
    for (; s[idx] != '\0'; idx++) {
        int d = char_val(s[idx]);
        if (d < 0 || d >= b1) {
            printf("INVALID\n");
            return;
        }
        val = val * b1 + d;
    }

    if (val == 0) {
        printf("0\n");
        return;
    }

    char out[128];
    int out_len = 0;
    while (val > 0) {
        out[out_len++] = val_char(val % b2);
        val /= b2;
    }
    if (negative) {
        out[out_len++] = '-';
    }
    for (int i = out_len - 1; i >= 0; i--) {
        putchar(out[i]);
    }
    putchar('\n');
}

int main(void) {
    int t;
    if (scanf("%d", &t) != 1) return 0;
    while (t--) {
        solve_one();
    }
    return 0;
}

