#include <stdio.h>

int main(void) {
    unsigned long long A, B;
    if (scanf("%llu %llu", &A, &B) != 2) return 0;

    unsigned long long best_x = A;
    unsigned long long max_steps = 0;
    unsigned long long overall_peak = 1;

    for (unsigned long long k = A; k <= B; k++) {
        unsigned long long curr = k;
        unsigned long long steps = 0;
        unsigned long long seq_peak = curr;

        while (curr != 1) {
            if (curr & 1) {
                curr = 3 * curr + 1;
            } else {
                curr /= 2;
            }
            if (curr > seq_peak) seq_peak = curr;
            steps++;
        }

        if (steps > max_steps) {
            max_steps = steps;
            best_x = k;
        }
        if (seq_peak > overall_peak) {
            overall_peak = seq_peak;
        }
    }

    printf("Longest: %llu with %llu steps\n", best_x, max_steps);
    printf("Peak: %llu\n", overall_peak);
    return 0;
}

