#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char num_str[32];
static long long target;
static int str_len;

static char results[10000][64];
static int result_count = 0;

static void dfs(int index, long long prev_operand, long long current_val, char *expr, int expr_len) {
    if (index == str_len) {
        if (current_val == target) {
            expr[expr_len] = '\0';
            strcpy(results[result_count++], expr);
        }
        return;
    }

    long long cur_num = 0;
    for (int i = index; i < str_len; i++) {
        if (i > index && num_str[index] == '0') break;
        cur_num = cur_num * 10 + (num_str[i] - '0');
        int len = i - index + 1;

        if (index == 0) {
            memcpy(expr + expr_len, num_str + index, len);
            dfs(i + 1, cur_num, cur_num, expr, expr_len + len);
        } else {
            // Try '*'
            expr[expr_len] = '*';
            memcpy(expr + expr_len + 1, num_str + index, len);
            dfs(i + 1, prev_operand * cur_num, current_val - prev_operand + prev_operand * cur_num, expr, expr_len + 1 + len);

            // Try '+'
            expr[expr_len] = '+';
            memcpy(expr + expr_len + 1, num_str + index, len);
            dfs(i + 1, cur_num, current_val + cur_num, expr, expr_len + 1 + len);

            // Try '-'
            expr[expr_len] = '-';
            memcpy(expr + expr_len + 1, num_str + index, len);
            dfs(i + 1, -cur_num, current_val - cur_num, expr, expr_len + 1 + len);
        }
    }
}

static int cmp_str(const void *a, const void *b) {
    return strcmp((const char *)a, (const char *)b);
}

int main(void) {
    if (scanf("%31s %lld", num_str, &target) != 2) return 0;
    str_len = strlen(num_str);
    char expr_buf[64];
    result_count = 0;
    dfs(0, 0, 0, expr_buf, 0);

    if (result_count == 0) {
        printf("NO SOLUTION\n");
    } else {
        qsort(results, result_count, sizeof(results[0]), cmp_str);
        for (int i = 0; i < result_count; i++) {
            printf("%s\n", results[i]);
        }
    }
    return 0;
}
